const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let entries=[],entry=null,currentId='',checkerId='',matched=false,checkVerdict='',misses=[],selection=0;
async function api(path,body){const response=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {ok:response.ok,status:response.status,data:await response.json()};}
function display(verdict,reason,metrics='',status='',action='Verification result'){$('#readout-action').textContent=action;$('#verdict').textContent=verdict;$('#reason').textContent=reason;$('#metrics').textContent=metrics;$('.readout').dataset.status=status;}
function failure(error){display('ERROR','The API could not load. Check the connection and try again.',error.message,'error');document.body.dataset.ready='error';}
const safe=fn=>(...args)=>Promise.resolve().then(()=>fn(...args)).catch(failure);
function groupedFiles(){const groups={};for(const file of entry?.closure||[]){const parts=file.path.split('/');const key=parts.length>1?parts.slice(0,-1).join('/'):'Package root';(groups[key]??=[]).push(file);}return Object.entries(groups);}
function node(key,x,y,w,h,label,sub,style=''){return `<g class="node ${style}" data-node="${key}" tabindex="0" role="button" aria-label="${esc(label+'; '+sub)}"><title>${esc(label+'; '+sub)}</title><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3"/><text class="label" x="${x+14}" y="${y+27}">${esc(label.length>29?label.slice(0,27)+'…':label)}</text><text class="sub" x="${x+14}" y="${y+49}">${esc(sub.length>36?sub.slice(0,34)+'…':sub)}</text></g>`;}
function draw(){if(!entry){$('#graph').innerHTML='<p class="notice">The full manifest is unavailable. Select an entry with evidence to inspect its graph.</p>';$('#graph-text').textContent='Full evidence unavailable.';$('#files').innerHTML='';return;}
const active=matched?'active':'';
const mobile=matchMedia('(max-width:650px)').matches;
const positions=mobile?[[24,16],[24,115],[24,214],[24,313],[24,412],[24,511]]:[[24,16],[348,16],[24,128],[348,128],[348,260],[24,260]];
const n=(key,index,label,sub,style='')=>node(key,...positions[index],mobile?310:260,76,label,sub,style);
let edges=mobile?`<path class="edge ${active}" d="M179 92 V103 H10 V252 H24"/><path class="edge ${active}" d="M179 290 V313"/><path class="edge ${active}" d="M179 389 V412"/><path class="edge" d="M334 54 H350 V153 H334"/>`:`<path class="edge ${active}" d="M154 92 V128"/><path class="edge ${active}" d="M284 166 H348"/><path class="edge ${active}" d="M478 204 V260"/><path class="edge" d="M284 54 H348"/>`;
let nodes=n('entry',0,entry.id,'Entry / '+entry.kind,active)+n('checker',1,entry.check?'Input checker':'No input checker',checkVerdict?checkVerdict==='no_checker'?'409 / choose a checker':'Verdict: '+checkVerdict:'Run check to light this node',checkVerdict==='accept'?'accept':checkVerdict==='reject'||checkVerdict==='no_checker'?'reject':'')+n('subject',2,entry.subject.artifact?.name||entry.subject.name,entry.subject.artifact?'Artifact / SHA-256 bound':'Subject / '+entry.subject.version,active)+n('closure',3,entry.closure.length+' delivered files',groupedFiles().length+' directory groups / expand',active)+n('runtime',4,entry.requires.join(', ')||'No extra libraries',entry.toolchain.replace('leanprover/',''),active);
if(misses.length){edges+=`<path class="edge dangling" d="M0 ${mobile?549:298} H24"/>`;nodes+=n('demand',5,'Unmatched demand',Object.values(misses[0].query||{}).join(', ')||'Unmatched request','demand');}
$('#graph').innerHTML=`<svg viewBox="0 0 ${mobile?'360 608':'632 360'}" role="group" aria-label="Selected proof package graph"><title>Entry, subject, closure and runtime dependencies</title>${edges}${nodes}</svg>`;
$('#graph-text').innerHTML=`<ul><li>Entry: ${esc(entry.id)}<ul><li>Concerns: ${esc(entry.subject.name)}${entry.subject.artifact?'; artifact '+esc(entry.subject.artifact.name):''}<ul><li>Delivers ${entry.closure.length} files in ${groupedFiles().length} directory groups.<ul><li>Requires ${esc(entry.requires.join(', ')||'no extra libraries')} and ${esc(entry.toolchain)}.</li></ul></li></ul></li><li>Input checker: ${entry.check?'available':'not available'}${checkVerdict?'; '+esc(checkVerdict):''}.</li></ul></li>${misses.map(m=>`<li>Unmatched demand, not connected to this proof: ${esc(JSON.stringify(m.query))}.</li>`).join('')}</ul>`;
$('#scope-mode').textContent=matched?'Lookup path matched':checkVerdict?'Checker: '+checkVerdict:'Selected package';
document.querySelectorAll('[data-node]').forEach(el=>{el.onclick=()=>inspectNode(el.dataset.node);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspectNode(el.dataset.node);}};});}
function inspectNode(key){if(!entry)return;if(key==='closure'){$('#closure-groups').open=!$('#closure-groups').open;$('#node-detail').textContent='Delivered closure: expand a directory below to inspect every file and SHA-256.';return;}if(key==='checker'){$('#input').focus();$('#node-detail').textContent=entry.check?'The checker verdict applies to your submitted input. Re-run it locally from the bundle.':'This entry has no input checker. Select the checker entry to check JSON.';return;}if(key==='entry'){$('#package').scrollIntoView({block:'start'});return;}if(key==='demand'){logs('demand').catch(failure);$('#recorder').scrollIntoView({block:'start'});return;}$('#node-detail').textContent=key==='subject'?entry.subject.artifact?`${entry.subject.artifact.name} / ${entry.subject.artifact.bytes} bytes / SHA-256 ${entry.subject.artifact.sha256}`:`Subject: ${entry.subject.name}, ${entry.subject.version}`:`Libraries: ${entry.requires.join(', ')||'None'}. Toolchain: ${entry.toolchain}.`;}
function renderEntry(){const e=entry;const recorded=e.replay.status==='recorded';$('#replay-status').className='replay'+(recorded?' recorded':'');$('#replay-status').textContent=recorded?'Recorded replay. Not re-run by fvapi.':'Real replay available. Re-run the bundle yourself.';$('#input').value=JSON.stringify(e.check?.example_input||{},null,2);$('#input-note').textContent=e.check?'Edit this JSON, then run the checker. A verdict does not replace proof replay.':'This entry has no input checker. Run check returns 409. Select the checker entry for runnable input.';$('#example').disabled=!e.check;$('#bundle').href='/v0/bundles/'+encodeURIComponent(e.id)+'.tar.gz';$('#bundle').hidden=false;$('#bundle-terms').textContent=e.licence.terms||'';$('#bundle-terms').hidden=!e.licence.terms;
$('#files').innerHTML=`<details id="closure-groups"><summary>Delivered closure: ${e.closure.length} files</summary>${groupedFiles().map(([dir,files])=>`<details><summary>${esc(dir)} (${files.length})</summary>${files.map(f=>`<div class="file"><strong>${esc(f.path)}</strong><br>${f.bytes} bytes<code>SHA-256 ${esc(f.sha256)}</code></div>`).join('')}</details>`).join('')}</details>`;
$('#entry').innerHTML=`<h3>${esc(e.title)}</h3><p class="claim">${esc(e.claim)}</p>${recorded?'<p class="notice"><strong>Recorded stub. Not re-run by fvapi.</strong> The transcript comes from an earlier run, not a verification by this service.</p>':''}<div class="entry-grid"><div><h4>Statements to match</h4>${e.statements.map(s=>`<p><strong>${esc(s.name)}</strong><br><small>${esc(s.file)}:${s.line}</small></p><pre>${esc(s.text)}</pre>`).join('')}<h4>Delivered files and SHA-256</h4><p>Every file is listed in the evidence scope. <button id="open-files">Inspect closure files</button></p><h4>Bundle-declared axioms</h4><pre>${esc(e.replay.expect_axioms.join('\n')||'None')}</pre><p class="axiom-note">Re-check uses your own allowlist, not this list (default: propext, Classical.choice, Quot.sound). Change it with <code>fvapi replay DIR --axioms a,b,c</code>.</p></div><div><h4>Replay on your machine</h4><pre id="command">${esc(e.replay.command)}</pre><button id="copy-command">Copy replay command</button><p><small>${esc(e.replay.note)}</small></p>${recorded?`<details><summary>Recorded transcript</summary><pre>${esc(e.replay.transcript||'No transcript provided.')}</pre></details>`:''}<dl><dt>Toolchain and requirements</dt><dd>${esc(e.toolchain)}<br>${esc(e.requires.join(', ')||'None')}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}${e.licence.terms?`<p class="notice licence-terms"><strong>${esc(e.licence.terms)}</strong></p>`:''}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(t=>`${esc(t.name)} / ${esc(t.spdx)}<br>${esc(t.source)}`).join('<br>'):'No third-party notices in this manifest.'}</dd><dt>Source</dt><dd>${esc(e.source.repo)}<br>Commit ${esc(e.source.commit)}<br>${e.source.paths.map(esc).join('<br>')}</dd></dl></div></div>`;
$('#copy-command').onclick=safe(async()=>{try{await navigator.clipboard.writeText(e.replay.command);$('#copy-command').textContent='Command copied';}catch{$('#copy-command').textContent='Select and copy the command above';}});$('#open-files').onclick=()=>{$('#closure-groups').open=true;$('#files').scrollIntoView({block:'start'});};}
async function select(id){const token=++selection;currentId=id;entry=null;matched=false;checkVerdict='';$('#bundle-terms').hidden=true;$('#bundle-terms').textContent='';display('READY','Select an input. Run the checker.','No input submitted for this entry');$('#response-wrap').hidden=true;$('#node-detail').textContent='Select a node to inspect it.';document.querySelectorAll('.switch').forEach(b=>b.setAttribute('aria-pressed',b.dataset.id===id));const r=await api('catalog/'+encodeURIComponent(id));if(token!==selection)return;if(!r.ok){$('#input').value='{}';$('#example').disabled=true;$('#bundle').hidden=true;const summary=entries.find(e=>e.id===id);$('#entry').innerHTML=`<h3>${esc(summary?.title||id)}</h3><p>${esc(summary?.claim||r.data.detail)}</p><p class="notice">${summary?.replay_status==='recorded'?'Recorded stub. Not re-run by fvapi. ':''}Full manifest unavailable in this mock. Select another entry to inspect its evidence.</p>`;$('#replay-status').textContent=summary?.replay_status==='recorded'?'Recorded replay. Not re-run by fvapi.':'Full manifest unavailable.';$('#replay-status').className='replay recorded';$('#input-note').textContent='Full manifest unavailable. Choose another entry to inspect its input.';draw();return;}entry=r.data;renderEntry();draw();}
async function logs(mode='answers'){const r=await api(mode);if(!r.ok)throw Error(r.data.detail||'Log unavailable');$('#answers').setAttribute('aria-pressed',mode==='answers');$('#demand').setAttribute('aria-pressed',mode==='demand');$('#log-title').textContent=mode==='demand'?'Unmatched requests saved for library work. No agent runs at request time.':'Answers returned by the service';const records=mode==='demand'?r.data.misses:r.data.answers;if(mode==='demand'){misses=r.data.misses||[];draw();}const counts=mode==='demand'?`<div class="counts"><strong>Counts by key</strong>${(r.data.by_key||[]).map(x=>`<div>${esc(x.key)}: ${x.count}</div>`).join('')||'<p>No unmatched keys. Look up a specification to start.</p>'}</div>`:'';$('#log').innerHTML=counts+(records?.length?records.map(x=>`<div class="record"><time>${esc(x.at)}</time><strong>${esc(x.kind||'Demand')}${x.verdict?' / '+esc(x.verdict):''}</strong><span>${esc(x.entry_id||JSON.stringify(x.query||{}))}</span><details><summary>${esc(x.answer_id||x.miss_id||'Record')} / full record</summary><pre>${esc(JSON.stringify(x,null,2))}</pre></details></div>`).join(''):'<p>No records yet. Run a lookup or a check.</p>');}
async function lookup(){const value=$('#query').value.trim();if(!value)return;const r=await api('lookup',{spec_id:value});if(r.ok){await select(r.data.entry?.id||r.data.entry_id||r.data.id||value);matched=true;display('FOUND','Matched proof package. Read the statement and re-run the proof.',`Lookup / HTTP ${r.status}`,'','Lookup');$('#lookup-status').textContent='Match found. The evidence path is highlighted.';}else{matched=false;$('#lookup-status').textContent=r.data.detail||'No match. Logged as demand. Try another specification ID.';display(r.status===404?'NO MATCH':'ERROR',r.data.detail||'Logged as demand. Try another specification ID.',`Lookup / HTTP ${r.status}`,r.status===404?'':'error','Lookup');$('#response').textContent=JSON.stringify(r.data,null,2);$('#response-wrap').hidden=false;if(r.status===404)misses=[r.data,...misses];}draw();await logs('answers');}
async function check(){let input;try{input=JSON.parse($('#input').value);}catch{display('INPUT ERROR','Invalid JSON. Correct the input and run again.','','error','Input checker');return;}const id=currentId;$('#run').disabled=true;try{const r=await api('checks/'+encodeURIComponent(id),input);if(id!==currentId)return;checkVerdict=r.ok?r.data.verdict:r.data.error;$('#response').textContent=JSON.stringify(r.data,null,2);$('#response-wrap').hidden=false;if(r.ok){const reason=r.data.output?.reason||'Read the checker response below.';display(String(r.data.verdict).toUpperCase(),typeof reason==='string'?reason:JSON.stringify(reason),`${r.data.elapsed_ms} ms / ${r.data.ran_on} / exit ${r.data.exit_code}`,r.data.verdict==='accept'?'accept':'reject','Input checker');if(r.data.recheck?.command)$('#input-note').textContent='Re-check locally: '+r.data.recheck.command;}else{display(r.status===409?'NO CHECKER':'ERROR',r.status===409?'Select the checker entry to run an input check.':r.data.detail,`Check / HTTP ${r.status}`,'error','Input checker');}draw();await logs();}finally{$('#run').disabled=false;}}
$('#lookup-form').onsubmit=e=>{e.preventDefault();safe(lookup)();};$('#run').onclick=safe(check);$('#example').onclick=()=>{if(entry?.check)$('#input').value=JSON.stringify(entry.check.example_input,null,2);};$('#answers').onclick=safe(()=>logs('answers'));$('#demand').onclick=safe(()=>logs('demand'));
async function init(){const r=await api('catalog');if(!r.ok)throw Error(r.data.detail);entries=r.data.entries;$('#count').textContent=entries.length+' entries / select a proof package';$('#catalog').innerHTML=entries.map(e=>`<button class="switch" data-id="${esc(e.id)}" aria-pressed="false"><b>${esc(e.subject.name)}</b><small>${esc(e.id)}<br>${esc(e.kind)} / ${e.replay_status==='recorded'?'recorded, not re-run':'real replay'}</small></button>`).join('');document.querySelectorAll('.switch').forEach(b=>b.onclick=safe(()=>select(b.dataset.id)));
// Catalog order differs between the fixture and server; runnable input comes from the manifest.
for(const candidate of entries.filter(e=>e.kind==='checker')){const result=await api('catalog/'+encodeURIComponent(candidate.id));if(result.ok&&result.data.check){checkerId=candidate.id;break;}}
const state=new URLSearchParams(location.search).get('state')||location.hash.slice(1)||'catalog';const recorded=entries.find(e=>e.replay_status==='recorded'&&e.id.includes('glm'))||entries.find(e=>e.replay_status==='recorded');await select(['recorded','check-409'].includes(state)&&recorded?recorded.id:checkerId||entries[0]?.id);const d=await api('demand');if(d.ok)misses=d.data.misses||[];draw();await logs();if(state==='lookup-hit'||state==='lookup-miss'){$('#query').value=state==='lookup-hit'?checkerId:'unmatched.example';await lookup();}if(['check-accept','check-reject','check-409'].includes(state)){if(state==='check-reject'){const input=JSON.parse($('#input').value);if(input.rows?.[0]?.weights)input.rows[0].weights[0]+=1;$('#input').value=JSON.stringify(input,null,2);}await check();}if(state==='demand')await logs('demand');if(state==='entry'){$('#closure-groups')?.setAttribute('open','');$('#closure-groups details')?.setAttribute('open','');$('#package').scrollIntoView({block:'start'});}if(state==='recorded')$('#package').scrollIntoView({block:'start'});if(['demand','answers'].includes(state))$('#recorder').scrollIntoView({block:'start'});await document.fonts.ready;document.body.dataset.ready='true';}
matchMedia('(max-width:650px)').addEventListener('change',draw);
init().catch(failure);
